   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Merging of VCD simple packages and VCD advanced packages into a VCD advanced package SHOULD be possible",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T47",
   "speaker": "Analyst",
   "act": "anything_else",
